pub fn source_input_data(ctx: &NodeContext, key: &str) -> Option<DataValue> {
    let arena = ctx.graph_context.context_arena.get_ref();
    let state = arena
        .get_toplevel()
        .node_states
        .get::<SourceInstanceProperties>(NodeId::default(), StateKey::Default)
        .ok();
    source_property_value(
        state,
        ctx.graph_context.frame_index(),
        key,
        ctx.graph_context
            .global_input_data
            .get(&format!("source_frame_input.{key}")),
    )
    .or_else(|| ctx.graph_context.global_input_data.get(key))
    .cloned()
}

fn source_property_value<'a>(
    state: Option<&'a SourceInstanceProperties>,
    frame: u64,
    key: &str,
    input: Option<&'a DataValue>,
) -> Option<&'a DataValue> {
    if state.is_none_or(|state| state.write_frames.get(key) != Some(&frame)) && input.is_some() {
        return input;
    }
    state.and_then(|state| state.values.get(key)).or(input)
}

pub fn source_player_property<'a>(
    player: &'a bevy_animation_graph::core::animation_graph_player::AnimationGraphPlayer,
    key: &str,
) -> Option<&'a DataValue> {
    let arena = player.get_context_arena();
    let state = arena.and_then(|arena| {
        arena
            .get_toplevel()
            .node_states
            .get::<SourceInstanceProperties>(NodeId::default(), StateKey::Default)
            .ok()
    });
    source_property_value(
        state,
        arena.map_or(0, |arena| arena.frame_index()),
        key,
        player.get_global_input_data(format!("source_frame_input.{key}")),
    )
}

/// Maintains a count of frames rendered since the start of the application.
///
/// [`FrameCount`] is incremented during [`Last`], providing predictable
/// behavior: it will be 0 during the first update, 1 during the next, and so forth.
///
/// # Overflows
///
/// [`FrameCount`] will wrap to 0 after exceeding [`u32::MAX`]. Within reasonable
/// assumptions, one may exploit wrapping arithmetic to determine the number of frames
/// that have elapsed between two observations – see [`u32::wrapping_sub()`].
#[derive(Debug, Default, Resource, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct FrameCount(pub u32);

/// Adds frame counting functionality to Apps.
#[derive(Default)]
pub struct FrameCountPlugin;

impl Plugin for FrameCountPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<FrameCount>();
        app.add_systems(Last, update_frame_count);
    }
}

/// A system used to increment [`FrameCount`] with wrapping addition.
///
/// See [`FrameCount`] for more details.
pub fn update_frame_count(mut frame_count: ResMut<FrameCount>) {
    frame_count.0 = frame_count.0.wrapping_add(1);
}
